from itertools import combinations

def calculate_E(a, b, c):
    """Calculates E(a, b, c) = ((a+b+c)(ab+bc+ca)+a+b+c) / (4abc)"""
    S = a + b + c
    P_pair = a*b + b*c + c*a
    P_triple = a * b * c

    numerator = S * (P_pair + 1)
    denominator = 4 * P_triple

    if denominator == 0:
        return None # Should not happen since a, b, c are positive

    return numerator / denominator

# Iterate over sums from 6 up to 12
results = {}

for s in range(6, 13):
    # Find combinations (a, b, c) such that a+b+c = s and a < b < c

    # A slightly brute force approach ensures we cover all distinct triples
    for a in range(1, s // 3):
        for b in range(a + 1, (s - a) // 2 + 1):
            c = s - a - b
            if c > b and c > 0:
                triple = tuple(sorted((a, b, c)))

                E = calculate_E(a, b, c)

                if E is not None and E == int(E):
                    n_val = int(E)
                    if n_val not in results:
                        results[n_val] = []
                    results[n_val].append(triple)

# Print the findings
print("Integer values of n found:")
for n, triples in sorted(results.items()):
    print(f"n = {n}: Found {len(triples)} triples, examples: {triples}")

